update public.twilio_response_rules as rules
set response_text = polished.response_text, updated_at = now()
from (values
  ('attendance_payment_pending', '🎉 *خطوة جميلة—سجّلنا رغبتك بالحضور!*\n\nرقم مشاركتك: *{participant_number}*\nالمبلغ المطلوب: *{price} ريال* ({price_label})\n\n💳 *بيانات التحويل*\n• STC Pay: {stc_pay}\n• {bank_name}\n• IBAN: {iban}\n\nأرسل الإيصال هنا كصورة واضحة أو PDF، وسنراجع الدفع ونؤكد مقعدك.'),
  ('attendance_paid', '🎉 *مقعدك مؤكد!*\n\nتم اعتماد دفعتك وتأكيد حضورك بنجاح. متحمسين نشوفك في الفعالية!'),
  ('attendance_waived', '🎉 *مقعدك مؤكد!*\n\nتم تأكيد حضورك مع إعفاء الدفع من المنظم. متحمسين نشوفك في الفعالية!'),
  ('attendance_confirmation_pending', '✨ *وصلنا طلب تأكيد حضورك*\n\nطلبك الآن *بانتظار اعتماد المنظم*. لن تتغير حالتك قبل المراجعة، وبإمكانك إرسال «اعتذار» إذا تغيّر قرارك.'),
  ('attendance_denial_pending', '🙏 *وصلنا اعتذارك عن الحضور*\n\nطلب الإلغاء الآن *بانتظار اعتماد المنظم*. لن تتغير حالتك قبل المراجعة، وبإمكانك إرسال «تأكيد» إذا تغيّر قرارك.'),
  ('attendance_denied', '🙏 *تم اعتماد اعتذارك*\n\nشكراً لأنك بلّغتنا. نتمنى نشوفك في فعالية قادمة أجمل!'),
  ('gender_any', '✨ *تم تحديث تفضيلك*\n\nاختيارك الآن: *أي جنس*. سنأخذ هذا التفضيل في الاعتبار عند إعداد المطابقة القادمة.'),
  ('gender_same', '✨ *تم تحديث تفضيلك*\n\nاختيارك الآن: *نفس الجنس*. سنأخذ هذا التفضيل في الاعتبار عند إعداد المطابقة القادمة.'),
  ('gender_different', '✨ *تم تحديث تفضيلك*\n\nاختيارك الآن: *جنس مختلف*. سنأخذ هذا التفضيل في الاعتبار عند إعداد المطابقة القادمة.'),
  ('age_expand_2', '🎯 *وسّعنا نطاق العمر لك*\n\nتمت إضافة *سنتين* للنطاق في هذه الفعالية فقط، مع بقاء تفضيلك الأساسي كما هو.'),
  ('age_expand_5', '🎯 *وسّعنا نطاق العمر لك*\n\nتمت إضافة *5 سنوات* للنطاق في هذه الفعالية فقط، مع بقاء تفضيلك الأساسي كما هو.'),
  ('age_keep_current', '👌 *أبقينا نطاقك كما هو*\n\nلن نجري أي تغيير على تفضيل العمر الحالي.'),
  ('discount_interested', '🎁 *سجّلنا اهتمامك بالعرض*\n\nسيتابع معك المنظم قريباً لإكمال التفاصيل.'),
  ('discount_declined', '👌 *وصلنا اختيارك*\n\nلن نفعّل العرض لك، ولم يتم إجراء أي تغيير آخر.'),
  ('arrival_on_way', '🚗 *بانتظارك!*\n\nسجّلنا أنك في الطريق وسنحافظ على مقعدك. توصل بالسلامة 🤍'),
  ('arrival_late', '⏰ *وصلنا أنك ستتأخر*\n\nسنحافظ على مقعدك. أرسل لنا وقت وصولك المتوقع إذا أمكن.'),
  ('arrival_cancel', '🙏 *وصلنا طلب إلغاء حضورك*\n\nسيبقى طلبك بانتظار اعتماد المنظم، ويمكنك التراجع بإرسال «تأكيد».'),
  ('auto_signup_enabled', '🔔 *فعّلنا إشعارات الفعاليات القادمة*\n\nسنراسلك عند توفر فعالية مناسبة. لن يتم تأكيد حضور أو طلب دفع دون موافقتك.\n\nلإيقافها في أي وقت، أرسل: *إيقاف*'),
  ('auto_signup_already', '🔔 *الإشعارات مفعّلة بالفعل*\n\nسنراسلك عند توفر فعالية مناسبة. لإيقافها أرسل: *إيقاف*'),
  ('auto_signup_stopped', '🛑 *تم إيقاف إشعارات التسجيل التلقائي*\n\nلن نضيفك تلقائياً إلى الفعاليات القادمة.'),
  ('preference_kept', '👌 *تم الإبقاء على اختيارك*\n\nلم نغيّر تفضيلك الحالي.'),
  ('receipt_received', '🧾 *وصلنا إيصال مشارك رقم {participant_number}*\n\nحالته الآن: *بانتظار المراجعة*. سنراسلك فور اعتماد الإيصال وتأكيد المقعد.'),
  ('receipt_unsupported', '📎 *لم نتمكن من قراءة المرفق كإيصال*\n\nأعد إرساله كصورة واضحة أو ملف PDF، وسنتولى الباقي.'),
  ('receipt_store_failed', '⚠️ *تعذر حفظ الإيصال هذه المرة*\n\nلم يُسجّل المرفق بعد. أعد إرساله كصورة واضحة أو PDF، وإذا تكرر الخطأ تواصل معنا على *0560899666*.'),
  ('unknown_message', 'أهلاً بك 👋\n\nتقدر ترد بإحدى الكلمات التالية:\n• *تأكيد* — لطلب تأكيد حضورك\n• *اعتذار* — إذا لن تتمكن من الحضور\n• *إيقاف* — لإيقاف إشعارات التسجيل التلقائي\n\nولرفع إيصال، أرسله هنا كصورة أو PDF.'),
  ('event_information', '✨ *وش فكرة التوافق الأعمى؟*\n\nتجربة اجتماعية منظّمة تمر فيها بجولات تعارف قصيرة، ثم تسجّل انطباعك بسرية لنساعدك في اكتشاف أفضل توافق.\n\n📘 *شرح التجربة وخطوات يوم الفعالية:*\n{tutorial_url}\n\nخذ دقيقتين لقراءة الشرح قبل وصولك، وبتكون الصورة كاملة وواضحة 🤍'),
  ('receipt_unknown_phone', '📱 *لم نتعرف على هذا الرقم*\n\nأرسل الإيصال من رقمك المسجل، أو تواصل معنا على *0560899666* لنساعدك.'),
  ('auto_signup_already_stopped', '👌 *الإشعارات متوقفة بالفعل*\n\nلم نغيّر أي شيء في حسابك.'),
  ('final_event_details', '📘 *قبل ما تجينا—خذ دقيقتين للشرح*\n{tutorial_url}\n\n📍 *المكان:* {location}\n🗺️ {map_url}\n📅 *التاريخ:* {event_date}\n🕰️ *الوقت:* {event_time}{arrival_suffix}\n\nاقرأ الخطوات قبل الوصول عشان تبدأ تجربتك بكل راحة. نشوفك هناك! ✨'),
  ('receipt_approved', '🎉 *تم اعتماد إيصالك!*\n\nدفعتك معتمدة ومقعدك في الفعالية *مؤكد*. متحمسين نشوفك!'),
  ('seat_waived_admin', '🎉 *تم تأكيد مقعدك!*\n\nاعتمد المنظم حضورك مع إعفاء الدفع. متحمسين نشوفك في الفعالية!'),
  ('receipt_rejected_reason', '⚠️ *يحتاج الإيصال إلى إعادة إرسال*\n\nالسبب: *{reason}*\n\nأرسل إيصالاً واضحاً وصحيحاً هنا، وسنراجعه من جديد.'),
  ('receipt_rejected_generic', '⚠️ *يحتاج الإيصال إلى إعادة إرسال*\n\nتأكد أن الصورة واضحة وتظهر تفاصيل التحويل، ثم أرسلها هنا كصورة أو PDF.')
) as polished(action_key, response_text)
where rules.action_key = polished.action_key;
